import assert from 'node:assert/strict';
import {mkdir,writeFile} from 'node:fs/promises';
import {createRequire} from 'node:module';
const ORIGIN='https://commerce-os-ops-center.vercel.app',PAGE='/stage8-sales-events',GATE='/stage8-candidate-promotion-gate';
const API='/api/product-master/shopling-sales-events',SHADOW='/api/china-order-manager/reentry-shadow?targetMonth=2026-10';
const ID='83a71972-4d53-4b4a-b599-7a6f76667e09',ASOF='2026-09-15T01:09:10.473Z',PLAN='sha256:6918e783e02feb644d188843c83b3130116b906738e5c4f5a58cdb99bfd2f390',EVENTS=12917;
function allow(url,method,top,body,armed){const u=new URL(url);if(u.origin!==ORIGIN||!top)return false;if(method==='GET')return [PAGE,GATE].includes(u.pathname)||u.pathname.startsWith('/_next/static/')||(u.pathname===API&&!u.search)||(u.pathname+u.search===SHADOW);return method==='POST'&&u.pathname===API&&!u.search&&['canary','full'].includes(armed)&&body&&Object.keys(body).length===3&&body.action===armed&&body.planFingerprint===PLAN&&body.confirmation===armed.toUpperCase();}
for(const action of ['start','refresh','run-next','approve','RESET_ZERO'])assert.equal(allow(ORIGIN+API,'POST',true,{action,planFingerprint:PLAN,confirmation:action.toUpperCase()},action),false);
for(const action of ['canary','full']){const body={action,planFingerprint:PLAN,confirmation:action.toUpperCase()};assert.ok(allow(ORIGIN+API,'POST',true,body,action));assert.equal(allow(ORIGIN+API,'POST',true,body,null),false);assert.equal(allow(ORIGIN+API,'POST',false,body,action),false);assert.equal(allow(ORIGIN+API,'POST',true,{...body,planFingerprint:'changed'},action),false);assert.equal(allow(ORIGIN+'/api/china-order-manager','POST',true,body,action),false);}
assert.ok(allow(ORIGIN+SHADOW,'GET',true,null,null));assert.equal(allow(ORIGIN+'/api/inventory-stock-control','GET',true,null,null),false);
console.log('PUBLICATION_NO_PURCHASE_BOUNDARY_PASS');
if(process.argv.includes('--self-test'))process.exit(0);
assert.equal(process.env.GITHUB_REF_NAME,'ops/sales-candidate-collect-20260915');
assert.equal(process.env.SALES_PUBLICATION_AUTHORIZATION,'OWNER_AUTHORIZED_VERIFIED_CANONICAL_SALES_ONLY');
assert.ok(Date.now()>=Date.parse(ASOF)&&Date.now()-Date.parse(ASOF)<24*60*60_000,'PINNED_ANALYSIS_EXPIRED');
const tools=createRequire(`${process.env.SALES_BROWSER_TOOLS}/package.json`);const {chromium}=tools('playwright');
const log={mode:'VERIFIED_CANONICAL_SALES_ONLY_NO_PURCHASING',startedAt:new Date().toISOString(),requestId:ID,analysisAsOf:ASOF,planFingerprint:PLAN,purchaseRequests:0,stockMutationRequests:0,canonicalRequests:[],verifiedCanonicalWrites:[],blockedRequests:0,gates:[],outcome:'NOT_STARTED'};
const dir='artifacts/sales-candidate-publish-20260915';await mkdir(dir,{recursive:true});
const browser=await chromium.launch({headless:true}),context=await browser.newContext({serviceWorkers:'block'}),page=await context.newPage();let armed=null,dialogAction=null;
await context.routeWebSocket('**/*',s=>s.close());
await context.route('**/*',async route=>{const r=route.request();let top=false,body=null;try{top=r.frame()===page.mainFrame();}catch{}if(r.method()==='POST'){try{body=r.postDataJSON();}catch{}}if(!allow(r.url(),r.method(),top,body,armed)){log.blockedRequests++;return route.abort('blockedbyclient');}if(r.method()==='POST'){log.canonicalRequests.push({action:armed,at:new Date().toISOString()});armed=null;}await route.continue();});
page.on('dialog',async d=>{const expected=dialogAction==='canary'?'Product Master 판매 이벤트 원장에 1건 카나리 적재합니다. 계속할까요?':dialogAction==='full'?'카나리 검증된 같은 계획으로 최근 360일 판매 이벤트를 전수 적재합니다. 계속할까요?':null;if(expected&&d.type()==='confirm'&&d.message()===expected){dialogAction=null;await d.accept();}else await d.dismiss();});
async function navigate(path){const r=await page.goto(ORIGIN+path,{waitUntil:'domcontentloaded',timeout:120000});assert.equal(r.status(),200,'PAGE_FAILED');assert.equal(new URL(page.url()).pathname,path,'AUTH_REDIRECT_STOP');}
async function status(){const result=await page.evaluate(async api=>{const r=await fetch(api,{cache:'no-store',signal:AbortSignal.timeout(120000)});return {http:r.status,data:await r.json()};},API);assert.equal(result.http,200);assert.equal(result.data.ok,true);const s=result.data.status;assert.equal(s.configured,true);assert.equal(s.requestId,ID,'SOURCE_CHANGED');assert.equal(s.analysisAsOf,ASOF);assert.equal(s.report?.planFingerprint,PLAN);assert.equal(s.report.sourceEventCount,EVENTS);assert.equal(s.report.unmappedRows,0);assert.equal(s.report.identityConflictCount,0);return s;}
async function checkGate(){await navigate(GATE);const text=await page.locator('main').innerText();const checks=await page.locator('main article').evaluateAll(rows=>rows.map(row=>({passed:row.querySelector('strong')?.textContent?.trim()==='PASS',key:row.querySelector('div.font-bold')?.textContent?.trim()??'unknown'})));const state=await page.locator('main section h2').first().innerText();const passed=['EXACT_MATCH','SAFE_CANONICAL_SUPERSET'].includes(state)&&text.includes('CANARY 적재 허용')&&text.includes(ID)&&text.includes(PLAN)&&checks.length>0&&checks.every(c=>c.passed);log.gates.push({at:new Date().toISOString(),state,passed,checks});console.log(JSON.stringify({gateState:state,passed,blockedChecks:checks.filter(c=>!c.passed).map(c=>c.key)}));return passed;}
async function apply(action){assert.equal(armed,null);armed=action;dialogAction=action;const pending=page.waitForResponse(r=>r.url()===ORIGIN+API&&r.request().method()==='POST',{timeout:290000});await page.getByRole('button',{name:action==='canary'?'1건 카나리 적재':'검증된 전수 적재',exact:true}).click({timeout:30000});const response=await pending;const payload=await response.json();assert.ok(response.ok()&&payload.ok===true,`PUBLICATION_HELD_${response.status()}`);assert.equal(payload.result?.ok,true);assert.equal(payload.result.planFingerprint,PLAN);const expected=action==='canary'?1:EVENTS;assert.equal(payload.result.selected,expected);assert.equal(payload.result.written,expected);log.verifiedCanonicalWrites.push({action,rows:expected,promotionFingerprint:payload.promotionGate?.promotionFingerprint??null});await page.waitForTimeout(2000);await page.waitForLoadState('domcontentloaded');await writeFile(`${dir}/result.json`,JSON.stringify(log,null,2));}
async function readShadow(){const result=await page.evaluate(async path=>{const r=await fetch(path,{cache:'no-store',signal:AbortSignal.timeout(180000)});return {http:r.status,data:await r.json()};},SHADOW);assert.ok([200,503].includes(result.http));const r=result.data.report;assert.ok(r);assert.equal(r.writesEnabled,false);assert.equal(r.actualPurchaseExecuted,false);assert.equal(r.approvalGranted,false);assert.equal(r.cashBudgetKrw,null);assert.ok(r.rows.every(row=>row.allocatedQuantity===0));log.shadow={http:result.http,generatedAt:r.generatedAt,state:r.state,demandAsOf:r.demandAsOf,demandSourceState:r.demandSourceState,managedSkuCount:r.managedSkuCount,quarantinedSkuCount:r.quarantinedSkuCount,summary:r.summary,blockerCodes:r.blockers.map(b=>b.code),recovery:r.recovery?.map(({id,state})=>({id,state})),rowIssueCounts:r.rows.flatMap(row=>row.issues).reduce((counts,issue)=>{counts[issue.code]=(counts[issue.code]??0)+1;return counts;},{}),actualPurchaseExecuted:false};console.log(JSON.stringify({shadow:log.shadow}));}
try{
 const gatePass=await checkGate();
 await navigate(PAGE);let s=await status();
 if(!gatePass){log.outcome='PROMOTION_GATE_BLOCKED_NO_WRITES';await readShadow();}
 else{
  if(s.state==='READY_CANARY'){await apply('canary');s=await status();}
  if(s.state==='READY_FULL'){
   assert.equal(s.canaryVerified,true,'CANARY_NOT_VERIFIED');assert.equal(await checkGate(),true,'GATE_CHANGED_BEFORE_FULL');await navigate(PAGE);s=await status();assert.equal(s.state,'READY_FULL');assert.equal(s.canaryVerified,true);await apply('full');s=await status();
  }
  assert.equal(s.state,'COMPLETED','OFFICIAL_PUBLICATION_NOT_COMPLETE');log.officialStatus={state:s.state,requestId:s.requestId,analysisAsOf:s.analysisAsOf,canaryVerified:s.canaryVerified,planFingerprint:s.report.planFingerprint};log.outcome='CANONICAL_PUBLICATION_VERIFIED';await readShadow();
 }
 console.log('CANONICAL_OPERATION_OUTCOME='+log.outcome);
}catch(error){log.outcome=log.canonicalRequests.length?'PUBLICATION_REQUIRES_READBACK_INSPECTION':'STOPPED_WITHOUT_PUBLICATION';log.failure=String(error.message).split('\n')[0].slice(0,160);console.error('CANONICAL_OPERATION_STOPPED_FOR_INSPECTION');process.exitCode=1;}
finally{log.finishedAt=new Date().toISOString();await writeFile(`${dir}/result.json`,JSON.stringify(log,null,2));await browser.close();}
